Theo định luật II Niu Tơn ta có $\ \left. \ \begin{array}{r}
\mathit{F}_{1}\  = \ ma_{1} \\
\mathit{F}_{2}\  = \ ma_{2}\  = \ 2\mathit{F}_{1}
\end{array} \right\}\mathbf{\Rightarrow}\frac{\mathit{F}_{1}}{\mathit{F}_{2}}\mathbf{=}\frac{1}{2}\mathbf{=}\frac{a_{1}}{a_{2}}\mathbf{\Rightarrow}a_{2}\mathbf{=}2a_{1}.$

\+ $\left\{ \begin{array}{r}
\mathit{m}_{1}\mathbf{=}\frac{\mathit{F}}{\mathit{a}_{1}} \\
\mathit{m}_{2}\mathbf{=}\frac{\mathit{F}}{\mathit{a}_{2}} \\
\mathit{m}\mathbf{=}\frac{\mathit{F}}{\mathit{a}}
\end{array} \right.\ \mathbf{\Rightarrow}\mathit{m}\mathbf{=}\mathit{m}_{1}\mathbf{+}\mathit{m}_{2}\mathbf{\Rightarrow}\frac{1}{\mathit{a}}\mathbf{=}\frac{1}{\mathit{a}_{1}}\mathbf{+}\frac{1}{\mathit{a}_{2}}\mathbf{\Rightarrow}\mathit{a}\mathbf{=}1,5\ m/s^{2}.$

Gia tốc của ô tô $\left( \begin{array}{r}
\mathit{a}_{1}\mathbf{=}\frac{\mathit{F}}{\mathit{m}_{1}}\mathbf{=}2\ m/s^{2} \\
\mathit{a}_{2}\mathbf{=}\frac{\mathit{F}}{\mathit{m}_{2}}\mathbf{=}6\ m/s^{2}
\end{array} \right.\ \mathbf{\Rightarrow}\mathit{m}_{1}\mathbf{=}3\mathit{m}_{2}\mathbf{\Rightarrow}\mathit{a}\mathbf{=}\frac{\mathit{F}}{2\mathit{m}_{1}\mathbf{+}3\mathit{m}_{2}}\mathbf{=}\frac{\mathit{F}}{9\mathit{m}_{2}}\mathbf{=}\frac{6}{9}\mathbf{=}0,67\ m/s^{2}.$

Gia tốc của ô tô $\left\{ \begin{array}{r}
\mathit{a}_{1}\mathbf{=}\frac{\mathit{F}_{1}}{\mathit{m}}\mathbf{=}2\ m/s^{2} \\
\mathit{a}_{2}\mathbf{=}\frac{\mathit{F}_{2}}{\mathit{m}}\mathbf{=}6\ m/s^{2}
\end{array} \right.\ \mathbf{\Rightarrow}\mathit{F}_{2}\mathbf{=}3\mathit{F}_{1}\mathbf{\Rightarrow}\mathit{a}\mathbf{=}\frac{2\mathit{F}_{1}\mathbf{+}3\mathit{F}_{2}}{\mathit{m}}\mathbf{=}\frac{11\mathit{F}_{1}}{\mathit{m}}\mathbf{=}11.2\mathbf{=}22\ m/s^{2}.$

